package gost341264_test

import (
	"crypto/cipher"
	"fmt"

	"gitverse.ru/uzer_007/gogost/v3/gost341264"
)

func Example() {
	key := []byte{
		0xff, 0xee, 0xdd, 0xcc, 0xbb, 0xaa, 0x99, 0x88,
		0x77, 0x66, 0x55, 0x44, 0x33, 0x22, 0x11, 0x00,
		0xf0, 0xf1, 0xf2, 0xf3, 0xf4, 0xf5, 0xf6, 0xf7,
		0xf8, 0xf9, 0xfa, 0xfb, 0xfc, 0xfd, 0xfe, 0xff,
	}
	plaintext := []byte{0xfe, 0xdc, 0xba, 0x98, 0x76, 0x54, 0x32, 0x10}

	block := gost341264.NewCipher(key)
	var _ cipher.Block = block

	ciphertext := make([]byte, gost341264.BlockSize)
	block.Encrypt(ciphertext, plaintext)

	fmt.Printf("%x\n", ciphertext)
	// Output: 4ee901e5c2d8ca3d
}
